package cn.enaium.fabricpvz.portable;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/**
 * The build identity of this jar, as the build wrote it
 * ({@code build-info.properties}, generated by the {@code buildInfo} task):
 * {@code SexyApp} logs it at startup and {@code -version} prints it.
 *
 * <p>The first version of the port hard-coded a build number of zero and an empty commit date - the
 * log therefore never carried them - and an empty product version. Everything here is read from the
 * resource when it is first asked for, and answers with an empty string (or zero) when the resource is
 * not there, so a jar built outside the repository states nothing rather than something wrong.
 */
public final class BuildInfo {

    private static final String RESOURCE = "/build-info.properties";

    private static Properties properties;

    private BuildInfo() {
    }

    private static synchronized Properties properties() {
        if (properties == null) {
            Properties loaded = new Properties();
            try (InputStream input = BuildInfo.class.getResourceAsStream(RESOURCE)) {
                if (input != null) {
                    loaded.load(input);
                }
            } catch (IOException ignored) {
                // No build identity available: every getter answers with its empty value.
            }
            properties = loaded;
        }
        return properties;
    }

    private static String get(String key) {
        return properties().getProperty(key, "");
    }

    /** The project version ({@code 1.2.5}, the version every artifact of this workspace carries). */
    public static String version() {
        return get("version");
    }

    /** How many commits the build is from: the value the game logs as its build number. */
    public static int buildNumber() {
        try {
            return Integer.parseInt(get("buildNumber"));
        } catch (NumberFormatException ignored) {
            return 0;
        }
    }

    /** The date of the commit the build is from (ISO-8601), or an empty string. */
    public static String commitDate() {
        return get("commitDate");
    }
}
